body:
Hi !

I observe a double free on IoT Hub Client on mqtt over websockets.
This happens when the device is deleted from the IoT hub when the client is currently registering.

I have modifed the example **iothub_client_sample_mqtt_websockets** you provide to be able to delete the device with the service client (file **[YOUR_PATH_TO_SDK]/iothub_client/samples/iothub_client_sample_mqtt_websockets/iothub_client_sample_mqtt_ws.c**):


```
// Copyright (c) Microsoft. All rights reserved.
// Licensed under the MIT license. See LICENSE file in the project root for full license information.

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#include "iothub_client.h"
#include "iothub_message.h"
#include "[YOUR_PATH_TO_SDK]/iothub_service_client/inc/iothub_service_client_auth.h"
#include "[YOUR_PATH_TO_SDK]/iothub_service_client/inc/iothub_registrymanager.h"
#include "azure_c_shared_utility/threadapi.h"
#include "azure_c_shared_utility/crt_abstractions.h"
#include "azure_c_shared_utility/platform.h"
#include "iothubtransportmqtt_websockets.h"
#include "../../../certs/certs.h"

/*String containing Hostname, Device Id & Device Key in the format:                         */
/*  "HostName=<host_name>;DeviceId=<device_id>;SharedAccessKey=[REDACTED_HIGH_CONFIDENCE_SECRET:azure_iot_shared_access_key]"                */
/*  "HostName=<host_name>;DeviceId=<device_id>;SharedAccessSignature=<device_sas_token>"    */
static const char* connectionString = "HostName=[PUT_YOUR_HOST_NAME_HERE];DeviceId=crashTest;SharedAccessKey=[REDACTED_HIGH_CONFIDENCE_SECRET:azure_iot_shared_access_key]";

static int callbackCounter;
static char msgText[1024];
static char propText[1024];
static bool g_continueRunning;
#define MESSAGE_COUNT 5
#define DOWORK_LOOP_NUM     10


typedef struct EVENT_INSTANCE_TAG
{
    IOTHUB_MESSAGE_HANDLE messageHandle;
    size_t messageTrackingId;  // For tracking the messages within the user callback.
} EVENT_INSTANCE;


static THREAD_HANDLE mqtt_thread_handle = NULL;

static IOTHUBMESSAGE_DISPOSITION_RESULT ReceiveMessageCallback(IOTHUB_MESSAGE_HANDLE message, void* userContextCallback)
{
    int* counter = (int*)userContextCallback;
    const char* buffer;
    size_t size;
    MAP_HANDLE mapProperties;
    const char* messageId;
    const char* correlationId;

    // Message properties
    if ((messageId = IoTHubMessage_GetMessageId(message)) == NULL)
    {
        messageId = "<null>";
    }

    if ((correlationId = IoTHubMessage_GetCorrelationId(message)) == NULL)
    {
        correlationId = "<null>";
    }

    // Message content
    if (IoTHubMessage_GetByteArray(message, (const unsigned char**)&buffer, &size) != IOTHUB_MESSAGE_OK)
    {
        (void)printf("unable to retrieve the message data\r\n");
    }
    else
    {
        (void)printf("Received Message [%d]\r\n Message ID: %s\r\n Correlation ID: %s\r\n Data: <<<%.*s>>> & Size=%d\r\n", *counter, messageId, correlationId, (int)size, buffer, (int)size);
        // If we receive the work 'quit' then we stop running
        if (size == (strlen("quit") * sizeof(char)) && memcmp(buffer, "quit", size) == 0)
        {
            g_continueRunning = false;
        }
    }

    // Retrieve properties from the message
    mapProperties = IoTHubMessage_Properties(message);
    if (mapProperties != NULL)
    {
        const char*const* keys;
        const char*const* values;
        size_t propertyCount = 0;
        if (Map_GetInternals(mapProperties, &keys, &values, &propertyCount) == MAP_OK)
        {
            if (propertyCount > 0)
            {
                size_t index;

                printf(" Message Properties:\r\n");
                for (index = 0; index < propertyCount; index++)
                {
                    (void)printf("\tKey: %s Value: %s\r\n", keys[index], values[index]);
                }
                (void)printf("\r\n");
            }
        }
    }

    /* Some device specific action code goes here... */
    (*counter)++;
    return IOTHUBMESSAGE_ACCEPTED;
}

static void SendConfirmationCallback(IOTHUB_CLIENT_CONFIRMATION_RESULT result, void* userContextCallback)
{
    EVENT_INSTANCE* eventInstance = (EVENT_INSTANCE*)userContextCallback;
    (void)printf("Confirmation[%d] received for message tracking id = %zu with result = %s\r\n", callbackCounter, eventInstance->messageTrackingId, ENUM_TO_STRING(IOTHUB_CLIENT_CONFIRMATION_RESULT, result));
    /* Some device specific action code goes here... */
    callbackCounter++;
    IoTHubMessage_Destroy(eventInstance->messageHandle);
}

void iothub_client_sample_mqtt_run(void)
{
    IOTHUB_CLIENT_LL_HANDLE iotHubClientHandle;

    EVENT_INSTANCE messages[MESSAGE_COUNT];

    g_continueRunning = true;
    srand((unsigned int)time(NULL));
    double avgWindSpeed = 10.0;

    callbackCounter = 0;
    int receiveContext = 0;

    if (platform_init() != 0)
    {
        (void)printf("Failed to initialize the platform.\r\n");
    }
    else
    {
        if ((iotHubClientHandle = IoTHubClient_LL_CreateFromConnectionString(connectionString, MQTT_WebSocket_Protocol)) == NULL)
        {
            (void)printf("ERROR: iotHubClientHandle is NULL!\r\n");
        }
        else
        {
            bool traceOn = false;
            IoTHubClient_LL_SetOption(iotHubClientHandle, "logtrace", &traceOn);

            // For mbed add the certificate information
            if (IoTHubClient_LL_SetOption(iotHubClientHandle, "TrustedCerts", certificates) != IOTHUB_CLIENT_OK)
            {
                printf("failure to set option \"TrustedCerts\"\r\n");
            }

            /* Setting Message call back, so we can receive Commands. */
            if (IoTHubClient_LL_SetMessageCallback(iotHubClientHandle, ReceiveMessageCallback, &receiveContext) != IOTHUB_CLIENT_OK)
            {
                (void)printf("ERROR: IoTHubClient_LL_SetMessageCallback..........FAILED!\r\n");
            }
            else
            {
                (void)printf("IoTHubClient_LL_SetMessageCallback...successful.\r\n");

                /* Now that we are ready to receive commands, let's send some messages */
                size_t iterator = 0;
                do
                {
                    if (iterator < MESSAGE_COUNT)
                    {
                        sprintf_s(msgText, sizeof(msgText), "{\"deviceId\":\"myFirstDevice\",\"windSpeed\":%.2f}", avgWindSpeed + (rand() % 4 + 2));
                        if ((messages[iterator].messageHandle = IoTHubMessage_CreateFromByteArray((const unsigned char*)msgText, strlen(msgText))) == NULL)
                        {
                            (void)printf("ERROR: iotHubMessageHandle is NULL!\r\n");
                        }
                        else
                        {
                            messages[iterator].messageTrackingId = iterator;
                            MAP_HANDLE propMap = IoTHubMessage_Properties(messages[iterator].messageHandle);
                            (void)sprintf_s(propText, sizeof(propText), "PropMsg_%zu", iterator);
                            if (Map_AddOrUpdate(propMap, "PropName", propText) != MAP_OK)
                            {
                                (void)printf("ERROR: Map_AddOrUpdate Failed!\r\n");
                            }

                            if (IoTHubClient_LL_SendEventAsync(iotHubClientHandle, messages[iterator].messageHandle, SendConfirmationCallback, &messages[iterator]) != IOTHUB_CLIENT_OK)
                            {
                                (void)printf("ERROR: IoTHubClient_LL_SendEventAsync..........FAILED!\r\n");
                            }
                            else
                            {
                                (void)printf("IoTHubClient_LL_SendEventAsync accepted message [%d] for transmission to IoT Hub.\r\n", (int)iterator);
                            }
                        }
                    }
                    IoTHubClient_LL_DoWork(iotHubClientHandle);
                    ThreadAPI_Sleep(1);

                    iterator++;
                } while (g_continueRunning);

                (void)printf("iothub_client_sample_mqtt has gotten quit message, call DoWork %d more time to complete final sending...\r\n", DOWORK_LOOP_NUM);
                for (size_t index = 0; index < DOWORK_LOOP_NUM; index++)
                {
                    IoTHubClient_LL_DoWork(iotHubClientHandle);
                    ThreadAPI_Sleep(1);
                }
            }
            IoTHubClient_LL_Destroy(iotHubClientHandle);
        }
        platform_deinit();
    }
}

static int threadMqtt(void* args) {
	iothub_client_sample_mqtt_run();
	return 0;
}

int main(void)
{
	IOTHUB_REGISTRYMANAGER_RESULT res = IOTHUB_REGISTRYMANAGER_OK;
	IOTHUB_REGISTRY_DEVICE_CREATE deviceCreate = {
		"crashTest", /*this device name must match with the one in connectionString variable */
		"QHyziNt4moHyCa/0Q2xngYHeg+QcIu7JonFzji545HY=", /*this key must match with the one in connectionString variable*/
		"HSIuQlKTqmz45ssy4fPIZlqwf8WooIWW51XU9g05UR8=",
		IOTHUB_REGISTRYMANAGER_AUTH_SPK/*IOTHUB_REGISTRYMANAGER_AUTH_X509_THUMBPRINT*/
		};
	IOTHUB_DEVICE device;

	IOTHUB_SERVICE_CLIENT_AUTH_HANDLE serviceClient = IoTHubServiceClientAuth_CreateFromConnectionString("HostName=[PUT_YOUR_HOST_NAME_HERE];SharedAccessKeyName=iothubowner;SharedAccessKey=[PUT_YOUR_KEY_HERE]");

	if(serviceClient != NULL) {
		IOTHUB_REGISTRYMANAGER_HANDLE registryManager = IoTHubRegistryManager_Create(serviceClient);
		if(registryManager != NULL) {
			(void)printf("Create device on Iot Hub\r\n");
			IoTHubRegistryManager_CreateDevice(registryManager, &deviceCreate, &device);
			if(res == IOTHUB_REGISTRYMANAGER_OK) {
				(void)printf("Create uMqtt connection\r\n");
				THREADAPI_RESULT thread_res = ThreadAPI_Create(&mqtt_thread_handle, threadMqtt, NULL);
				if(thread_res == THREADAPI_OK) {
					(void)printf("Delete device on Iot Hub\r\n");
					res = IoTHubRegistryManager_DeleteDevice(registryManager, "crashTest");
					if(res == IOTHUB_REGISTRYMANAGER_OK) {
						(void)printf("Should lead to crash\r\n");
					} else {
						(void)printf("Error to delete device (%d)\r\n", (int)res);
					}

					int ret = 0;
					thread_res = ThreadAPI_Join(mqtt_thread_handle, (int*) &ret);
					if(thread_res != THREADAPI_OK) {
					  (void)printf("Error to ThreadAPI_Join (%d)\r\n", (int)thread_res);
					}

				} else {
					(void)printf("Error to create thread (%d)\r\n", (int)thread_res);
				}
			} else {
				(void)printf("Error to create device (%d)\r\n", (int)res);
			}	
			IoTHubRegistryManager_Destroy(registryManager);		
		} else {
			(void)printf("Error to create registry manager\r\n");
		}
		IoTHubServiceClientAuth_Destroy(serviceClient);
	} else {
		(void)printf("Error to create service client handle\r\n");
	}



    return 0;
}

```

I also modified a bit the **iothub_client/CMakeLists.txt** to link the service client library:

target_link_libraries(iothub_client_mqtt_ws_transport "[YOUR_PATH_TO_SDK]/cmake/iotsdk_linux/iothub_service_client/libiothub_service_client.a")

Normaly you should be able to reproce the bug with those modifications.

Environment: Linux Ubuntu 16.04
Branch: master
Commit: aa0d5560701d44d7c9003fbf16f4a71b8bc94e18

Thank you.

Regards.

Alexandre Marechal

