#define NUMDEVICES 4

typedef struct DEVICEKEYVALUE_TAG {
		const char* id;
		const char* key;
} DeviceKeyValue;

DeviceKeyValue DeviceList[NUMDEVICES];

static const char* hubName = "......";
static const char* hubSuffix = "......";


