body:
The javadoc of the ```startBeaconScan``` method in ```BluetoothLeBeaconScanner``` is

```
    /**
     * Start a scan for beacons of given duration in seconds.
     * 
     * @param duration
     *            The scan duration in seconds
     * @throws KuraBluetoothCommandException
     */
```

However, its implementation uses the ```duration``` variable as milliseconds:

```
    @Override
    public void startBeaconScan(long timeout) throws KuraBluetoothCommandException {
        try {
            this.beaconManager.startBeaconScan(this.adapter.getInterfaceName());
            this.isScanning = true;
            long start = System.currentTimeMillis();
            while (System.currentTimeMillis() - start < timeout) {
                Thread.sleep(500);
            }
            stopBeaconScan();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
```

Should change this two function:

@Override
    public void createCloudServiceFromFactory(GwtXSRFToken xsrfToken, String factoryPid, String cloudServicePid)
            throws GwtKuraException {
        checkXSRFToken(xsrfToken);
        if (factoryPid == null || factoryPid.trim().isEmpty() || cloudServicePid == null
                || cloudServicePid.trim().isEmpty()) {
            throw new GwtKuraException(GwtKuraErrorCode.ILLEGAL_NULL_ARGUMENT);
        }

        final AtomicReference<CloudConnectionFactory> ref = new AtomicReference<>();

        withAllCloudConnectionFactories(service -> {

            if (!service.getFactoryPid().equals(factoryPid) || ref.get() != null) {
                return;
            }

            ref.set(service);

        });

        try {
            ref.get().createConfiguration(cloudServicePid);
        } catch (KuraException e) {
            throw new GwtKuraException("Failed to create cloud stack");
        }

    }

    @Override
    public void deleteCloudServiceFromFactory(GwtXSRFToken xsrfToken, String factoryPid, String cloudServicePid)
            throws GwtKuraException {
        if (factoryPid == null || factoryPid.trim().isEmpty() || cloudServicePid == null
                || cloudServicePid.trim().isEmpty()) {
            throw new GwtKuraException(GwtKuraErrorCode.ILLEGAL_NULL_ARGUMENT);
        }

        final AtomicReference<CloudConnectionFactory> ref = new AtomicReference<>();

        withAllCloudConnectionFactories(service -> {

            if (!service.getFactoryPid().equals(factoryPid) || ref.get() != null) {
                return;
            }

            ref.set(service);

        });

        try {
            ref.get().deleteConfiguration(cloudServicePid);
        } catch (KuraException e) {
            throw new GwtKuraException("Failed to delete cloud stack");
        }

    }


to this:

    @Override
    public void createCloudServiceFromFactory(GwtXSRFToken xsrfToken, String factoryPid, String cloudServicePid)
            throws GwtKuraException {
        checkXSRFToken(xsrfToken);
        if (factoryPid == null || factoryPid.trim().isEmpty() || cloudServicePid == null
                || cloudServicePid.trim().isEmpty()) {
            throw new GwtKuraException(GwtKuraErrorCode.ILLEGAL_NULL_ARGUMENT);
        }

        final AtomicBoolean ref = new AtomicBoolean(false);
        withAllCloudConnectionFactories(service -> {

            if (!service.getFactoryPid().equals(factoryPid) || ref.get()) {
                return;
            }

            ref.set(true);
            try {
                service.createConfiguration(cloudServicePid);
            } catch (KuraException e) {
                throw new GwtKuraException("Failed to create cloud stack");
