[2018-07-18T09:13:15Z | maggu2810 | comment]
@lolodomo For javax.ws.rs stuff there are a few things you can request to be injected...

Here an short example (stripped down of some code of mine):

```Java
package ...;

import javax.ws.rs.container.ContainerRequestContext;
import javax.ws.rs.container.ContainerRequestFilter;
import javax.ws.rs.container.PreMatching;
import javax.ws.rs.container.ResourceInfo;
import javax.ws.rs.core.Application;
import javax.ws.rs.core.Context;
import javax.ws.rs.core.HttpHeaders;
import javax.ws.rs.core.Request;
import javax.ws.rs.core.Response;
import javax.ws.rs.core.SecurityContext;
import javax.ws.rs.core.UriInfo;
import javax.ws.rs.ext.Provider;
import javax.ws.rs.ext.Providers;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ... {

    private final Logger logger = LoggerFactory.getLogger(EshRestFilter.class);

    @Context
    private ResourceInfo resourceInfo;

    @Context
    private Application application;

    @Context
    private UriInfo uriInfo;

    @Context
    private Request request;

    @Context
    private HttpHeaders httpHeaders;

    @Context
    private SecurityContext securityContext;

    @Context
    private Providers providers;

    @Override
    public void foo() throws IOException {
        logger.trace("resourceInfo: class: {}, method: {}", resourceInfo.getResourceClass(),
                resourceInfo.getResourceMethod());

        logger.trace("application: {}", application);

        logger.trace("uriInfo: absolutePath: {}, path-decoded: {}, path: {}, baseUri: {}, requestUri: {}",
                uriInfo.getAbsolutePath(), uriInfo.getPath(), uriInfo.getPath(false), uriInfo.getBaseUri(),
                uriInfo.getRequestUri());

        logger.trace("request: method: {}", request.getMethod());

        logger.trace("httpHeaders: requestHeaders: {}", httpHeaders.getRequestHeaders());

        logger.trace("securityContext: authenticationScheme: {}, userPrincipal: {}, isSecure: {}",
                securityContext.getAuthenticationScheme(), securityContext.getUserPrincipal(),
                securityContext.isSecure());

        logger.trace("providers: {}", providers);
    }
}
```

