FWIW, I was having the same issue. For some reason if I try to interact with my i2c sensor 
straight from the loop() function it does not work, instead, if I define a loop handler function 
and pass it on to Homie and interact from there, it works.

The sensor I'm using is not BME280 but this https://www.atlas-scientific.com/product_pages/circuits/ezo_flow.html so this seems to be about the interaction between homie and the Wire library and not a specific sensor.

This sensor has a led that blinks when it gets a command so it's easy to know what's going on.
As mentioned before, if I do all the Wire stuff on the loop() function after the Homie.loop() call instead,
the led in the sensor does not even blink and readings are null, this suggests that the command somehow is not being sent over the i2c bus. I have no clue why ...

Here is the code that worked form me :

```c++
#include <Homie.h>
#include <Wire.h>

HomieNode sensorNode("sensor", "Sensor", "sensor");

void loopHandler() {
    Wire.beginTransmission(104);
    Wire.write("R\0");
    Wire.endTransmission();
    delay(500);
    Wire.requestFrom(104, 20, 1);
    //the first byte is the response code, we read this separately.
    byte code = Wire.read();
    char buffer[20];
    if(code == 1){
      Serial.println("Success");
      byte i = 0;
      while (Wire.available()) {
        buffer[i] = Wire.read();
        if (buffer[i] == 0){
          Wire.endTransmission();
          break;
        }
        ++i;
      }
      Serial.print("Response : ");
      Serial.println(buffer);
      sensorNode.setProperty("value").send(String(buffer));
    }else if (code == 2){
      Serial.println("Failure");
    }else if (code == 254){
      Serial.println("Not finished");
    }else if (code == 255){
      Serial.println("No data");
    }
}

void setup() {

  Serial.begin(115200);
  Serial << endl << endl;

  Wire.begin();

  Homie_setFirmware("i2c-test", "1.0.0");
  Homie.setLoopFunction(loopHandler);

  sensorNode.advertise("value").setName("Value").setDatatype("double");

  Homie.setup();
}

void loop(){
    Homie.loop();
    // without this delay it will not connect to the MQTT broker :S
    delay(100);
}
