    // Create the properties to log in
    final Properties properties = new Properties();
    properties.setProperty("org", ORGID);
    properties.setProperty("type", GATEWAY_TYPE);
    properties.setProperty("id", GATEWAY_ID);
    properties.setProperty("auth-method", "token");
    properties.setProperty("auth-token", TOKEN);

    // Create a DeviceData object - option 1 => NPE at line 78
    final DeviceData deviceData1 = new DeviceData.Builder()
        .typeId(GATEWAY_TYPE).deviceId(GATEWAY_ID).build();

    // Create a DeviceData object - option 2 => NPE at line 78
    final DeviceData deviceData2 = new DeviceData.Builder()
        .typeId(GATEWAY_TYPE).deviceId(GATEWAY_ID)
        .metadata(null).build();

    // Create a DeviceData object - option 3 
    // => NPE at com.ibm.iotf.devicemgmt.gateway.ManagedGateway.sendDeviceManageRequest(ManagedGateway.java:666)
    final DeviceMetadata metadata3 = new DeviceMetadata(null);
    final DeviceData deviceData3 = new DeviceData.Builder()
        .typeId(GATEWAY_TYPE).deviceId(GATEWAY_ID)
        .metadata(metadata3).build();

    // Create a DeviceData object - option 4 
    // => this clears out the metadata in Watson IoT on the Gateway
    final DeviceMetadata metadata4 = new DeviceMetadata(new JsonObject());
    final DeviceData deviceData4 = new DeviceData.Builder()
        .typeId(GATEWAY_TYPE).deviceId(GATEWAY_ID)
        .metadata(metadata4).build();

    // Create a DeviceData object - option 5 => Does not compile
