    //    .metadata(metadata5).build();


    // Create the managed gateway using properties and deviceData 
    final ManagedGateway managedGateway = new ManagedGateway(properties, deviceData1);

    managedGateway.connect();

    // Create a separate thread for the next actions
    new Thread(() -> {
      try {
        // publish a simple random message to prove that the MQTT connection works
        publishAliveMessage(managedGateway);

        // send manage request
        final boolean result = managedGateway.sendGatewayManageRequest(0, false, false);
        System.out.println("sendManageRequest: " + result);

        // add a property change listeners to the deviceInfo
        managedGateway.getGatewayDeviceData().getDeviceInfo().addPropertyChangeListener(evt -> {
          System.out.println("PropertyChangeEvent:" + evt.getPropertyName());
