        mbed_stats_stack_get(&stack);
        char bufff[STRING_BUFFER_32] = {0};
        sprintf(bufff, "cs %d ac %d", heap.current_size, heap.alloc_cnt);
        Screen.print(0, "heap");
        Screen.print(1, bufff);
        Screen.print(2, "stack");
        memset(bufff, 0, STRING_BUFFER_32);
        sprintf(bufff, "rs %d sc %d", stack.reserved_size, stack.stack_cnt);
        Screen.print(3, bufff);
```

In the GetStarted Example there are useless comparisons like
 if (humidity != humidity) 
{
json_object_set_null(root_object, "humidity");
}

Those could be confusing for starters with the DevKit.
Please remove them.

